import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"多帳本功能說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/04-multi-ledger-guide.md","filePath":"v1/zh-HK/guide/04-multi-ledger-guide.md"}'),t={name:"v1/zh-HK/guide/04-multi-ledger-guide.md"};function o(n,a,h,s,d,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="多帳本功能說明" tabindex="-1">多帳本功能說明 <a class="header-anchor" href="#多帳本功能說明" aria-label="Permalink to &quot;多帳本功能說明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>你可以建立多個帳本，把不同用途的收支分開管理。每個帳本都可以獨立設定名稱、貨幣、分類與統計資料。</p><p>常見使用情境：</p><ul><li>個人帳本</li><li>家庭帳本</li><li>旅遊帳本</li><li>寶寶帳本</li><li>汽車帳本</li><li>裝修帳本</li><li>生意帳本</li></ul><hr><h2 id="🚀-建立與切換" tabindex="-1">🚀 建立與切換 <a class="header-anchor" href="#🚀-建立與切換" aria-label="Permalink to &quot;🚀 建立與切換&quot;">​</a></h2><h3 id="建立新帳本" tabindex="-1">建立新帳本 <a class="header-anchor" href="#建立新帳本" aria-label="Permalink to &quot;建立新帳本&quot;">​</a></h3><ol><li>打開考拉記帳 App</li><li>點擊 <strong>設定</strong> → <strong>帳本管理</strong></li><li>點擊右上角 <strong>+</strong></li><li>填寫帳本資訊（名稱/描述/圖標/貨幣）</li><li>點擊 <strong>保存</strong></li></ol><h3 id="切換帳本" tabindex="-1">切換帳本 <a class="header-anchor" href="#切換帳本" aria-label="Permalink to &quot;切換帳本&quot;">​</a></h3><ol><li>進入 <strong>帳本管理</strong></li><li>在帳本列表點擊要切換的帳本卡片</li></ol><h2 id="🗑️-刪除帳本" tabindex="-1">🗑️ 刪除帳本 <a class="header-anchor" href="#🗑️-刪除帳本" aria-label="Permalink to &quot;🗑️ 刪除帳本&quot;">​</a></h2><ol><li>在帳本管理中打開目標帳本的詳情頁</li><li>點擊 <strong>刪除帳本</strong></li><li>確認刪除</li></ol><p>⚠️ 刪除後會移除該帳本資料；如已開啟雲端同步，後續同步也會從雲端刪除。此操作不可在 App 內復原，請謹慎。</p><hr><h2 id="💰-帳本貨幣-本位幣" tabindex="-1">💰 帳本貨幣（本位幣） <a class="header-anchor" href="#💰-帳本貨幣-本位幣" aria-label="Permalink to &quot;💰 帳本貨幣（本位幣）&quot;">​</a></h2><ul><li>每個帳本都可以設定自己的貨幣。</li><li>修改帳本貨幣後，金額顯示與統計可能會跟著調整。</li></ul><blockquote><p>💡 提示：貨幣與匯率的更多說明請看 <a href="./05-exchange-rate-guide">匯率說明</a>。</p></blockquote><hr><h2 id="📊-資料隔離" tabindex="-1">📊 資料隔離 <a class="header-anchor" href="#📊-資料隔離" aria-label="Permalink to &quot;📊 資料隔離&quot;">​</a></h2><ul><li><strong>帳單</strong>：帳本之間互相獨立</li><li><strong>分類</strong>：帳本之間互相獨立</li><li><strong>標籤</strong>：帳本之間互相獨立</li><li><strong>統計</strong>：帳本之間互相獨立</li></ul><blockquote><p>📝 注意：<strong>帳戶是裝置級別共用</strong>，不同帳本可以使用同一個帳戶。</p></blockquote><hr><h2 id="🔄-帳本同步" tabindex="-1">🔄 帳本同步 <a class="header-anchor" href="#🔄-帳本同步" aria-label="Permalink to &quot;🔄 帳本同步&quot;">​</a></h2><p>若已登入並開啟雲端同步，帳本也會同步到雲端，支援多裝置使用。</p><hr><h2 id="🔧-常見問題" tabindex="-1">🔧 常見問題 <a class="header-anchor" href="#🔧-常見問題" aria-label="Permalink to &quot;🔧 常見問題&quot;">​</a></h2><h3 id="q1-可以建立多少個帳本" tabindex="-1">Q1：可以建立多少個帳本？ <a class="header-anchor" href="#q1-可以建立多少個帳本" aria-label="Permalink to &quot;Q1：可以建立多少個帳本？&quot;">​</a></h3><p>最多可建立 <strong>50</strong> 個帳本。</p><h3 id="q2-帳戶是帳本級別的嗎" tabindex="-1">Q2：帳戶是帳本級別的嗎？ <a class="header-anchor" href="#q2-帳戶是帳本級別的嗎" aria-label="Permalink to &quot;Q2：帳戶是帳本級別的嗎？&quot;">​</a></h3><p>不是。帳戶是裝置級別的，所有帳本共用。</p><hr><p><strong>最後更新</strong>：2026 年 1 月</p>',33)])])}const p=l(t,[["render",o]]);export{g as __pageData,p as default};
